-- 分场景计算995阈值
CREATE TEMPORARY VIEW every_scene_995_step1_${grass_region_without_quote} AS
select
     is_item_card
    ,user_id
    ,is_ads
    ,source1_is_ads
    ,source2_is_ads
    ,case
       when reporting_business_line in ('Search') and reporting_module in ('Global Search') then 'Search'
       when reporting_module in ('Daily Discover') then 'Daily Discover'
       when reporting_object in ('you may also like') then 'You May Also Like'
       when reporting_business_line in ('Rcmd') and reporting_module in ('User Scenario') and reporting_object in ('post purchase') then 'Post Purchase'
       when reporting_business_line in ('Shop(Non Rcmd)') or (reporting_business_line = 'Rcmd' and reporting_module = 'Private Domin') then 'Shop'
       else '' -- 任何非归因数据都需要有场景
     end as mapping_general
    ,case
       when source1_reporting_business_line in ('Search') and source1_reporting_module in ('Global Search') then 'Search'
       when source1_reporting_module in ('Daily Discover') then 'Daily Discover'
       when source1_reporting_object in ('you may also like') then 'You May Also Like'
       when source1_reporting_business_line in ('Rcmd') and source1_reporting_module in ('User Scenario') and source1_reporting_object in ('post purchase') then 'Post Purchase'
       else ''
     end as source1_mapping_general
    ,case
       when source2_reporting_business_line in ('Search') and source2_reporting_module in ('Global Search') then 'Search'
       when source2_reporting_module in ('Daily Discover') then 'Daily Discover'
       when source2_reporting_object in ('you may also like') then 'You May Also Like'
       when source2_reporting_business_line in ('Rcmd') and source2_reporting_module in ('User Scenario') and source2_reporting_object in ('post purchase') then 'Post Purchase'
       else ''
     end as source2_mapping_general
    ,order_cnt
    ,gmv
from log_data_raw_${grass_region_without_quote}
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW every_scene_995_step2_${grass_region_without_quote} AS
select
     is_item_card
    ,user_id
    ,is_ads
    ,mapping_general
    ,order_cnt
    ,gmv
from every_scene_995_step1_${grass_region_without_quote}
where mapping_general != ''
union all
select
     'false' as is_item_card
    ,user_id
    ,source1_is_ads as is_ads
    ,source1_mapping_general as mapping_general
    ,order_cnt
    ,gmv
from every_scene_995_step1_${grass_region_without_quote}
where source1_mapping_general in ('Search','Daily Discover','You May Also Like','Post Purchase')
and source1_mapping_general != mapping_general
union all
select
     'false' as is_item_card
    ,user_id
    ,source2_is_ads as is_ads
    ,source2_mapping_general as mapping_general
    ,order_cnt
    ,gmv
from every_scene_995_step1_${grass_region_without_quote}
where source2_mapping_general in ('Search','Daily Discover','You May Also Like','Post Purchase')
and source2_mapping_general != mapping_general and source2_mapping_general != source1_mapping_general
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW every_scene_995_${grass_region_without_quote} AS
select
     is_ads
    ,is_item_card
    ,mapping_general
    ,approx_percentile(gpo,0.995) as gpo_pct
from(
    select
         user_id
        ,mapping_general
        ,if(grouping(is_ads)=1,'__ALL__',is_ads) as is_ads
        ,if(grouping(is_item_card)=1,'__ALL__',is_item_card) as is_item_card
        ,coalesce(sum(gmv)/sum(order_cnt),0) as gpo
    from every_scene_995_step2_${grass_region_without_quote}
    group by
         user_id
        ,mapping_general
        ,is_ads
        ,is_item_card
    GROUPING SETS ((user_id,mapping_general,is_ads,is_item_card),(user_id,mapping_general,is_item_card),(user_id,mapping_general,is_ads),(user_id,mapping_general))
) a
group by
     is_ads
    ,is_item_card
    ,mapping_general
;
--sql_divide_splitter--

